1	use callisto_model::PackageId;
2	use globset::{Glob, GlobMatcher};
3	
4	/// A glob pattern for matching package names in `[[package-set]]` blocks.
5	///
6	/// Unlike `[[package]]` which uses an exact `PackageId` match,
7	/// `[[package-set]]` allows a single rule to target many packages at once
8	/// via a glob (e.g. `"pkg-*"` matches `pkg-a`, `pkg-b`, etc.).
9	///
10	/// Ecosystem prefixes in the pattern are respected: `"cargo:pkg-*"` only
11	/// matches Cargo packages; a bare `"pkg-*"` matches packages in any ecosystem
12	/// that have a matching name.
13	#[derive(Clone, Debug)]
14	pub struct PackagePattern {
15	    raw: String,
16	    matcher: GlobMatcher,
17	}
18	
19	impl PackagePattern {
20	    pub fn parse(s: &str) -> Result<Self, globset::Error> {
21	        let glob = Glob::new(s)?;
22	        Ok(Self {
23	            raw: s.to_string(),
24	            matcher: glob.compile_matcher(),
25	        })
26	    }
27	
28	    /// Returns true when the given `PackageId`'s name matches the glob pattern.
29	    ///
30	    /// Matching is done against the package name only (no ecosystem prefix),
31	    /// so `"pkg-*"` matches both `cargo:pkg-a` and `npm:pkg-b`.
32	    pub fn matches(&self, id: &PackageId) -> bool {
33	        self.matcher.is_match(id.name())
34	    }
35	
36	    pub fn as_str(&self) -> &str {
37	        &self.raw
38	    }
39	}
40	
41	impl std::fmt::Display for PackagePattern {
42	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
43	        f.write_str(&self.raw)
44	    }
45	}
