+        let root = tmp.path();
+        // "cascade_mode" is a common typo for [cascade] mode = "always"
+        fs::write(
+            root.join("callisto.toml"),
+            "[cascade]\ncascade_mode = \"always\"\n",
+        )
+        .expect("write callisto.toml");
+
+        let result = load(root);
+        assert!(
+            result.is_err(),
+            "load() must reject unknown field 'cascade_mode'; \
