+    let locator = callisto_graph::locate::IgnoreWalkLocator::new(root);
+    let result = Workspace::load(root.to_path_buf(), &locator, &runner);
+
+    match result {
+        Ok(_) => panic!(
+            "Workspace::load must return Err when two packages share the same name, but got Ok"
